"""Write a resolved version into a file inside the project."""

from __future__ import annotations

import contextlib
import os
import tempfile
from dataclasses import dataclass
from enum import StrEnum
from pathlib import Path

PYTHON_MODULE = """\
# file generated by calver-scm
# don't change, don't track in version control

__all__ = ["__version__", "version"]

__version__ = version = {version!r}
"""


class WriteError(Exception):
    """The version file cannot be written, with a message fit to show the user."""


class WriteStatus(StrEnum):
    """What writing a version file did, or in a dry run would do."""

    WROTE = "wrote"
    UNCHANGED = "unchanged"
    WOULD_WRITE = "would write"


@dataclass(frozen=True, slots=True)
class WriteResult:
    """The outcome of one write, with the path as shown to the user."""

    status: WriteStatus
    path: str
    content: str


def render(target: Path, version: str) -> str:
    """The file's content: a Python module for `.py`, otherwise the bare version."""
    if target.suffix == ".py":
        return PYTHON_MODULE.format(version=version)
    return f"{version}\n"


def write_version_file(
    root: Path, target: Path, version: str, *, dry_run: bool = False
) -> WriteResult:
    """Write `version` to `target`, which must be inside `root`.

    `target` is relative to `root` or absolute. It is resolved first, following
    symlinks, so a path cannot leave the project by `..` or by a link. The file
    is replaced in one step, and left alone when it already holds the content.
    """
    base = root.resolve()
    path = (base / target).resolve()
    if not path.is_relative_to(base):
        raise WriteError(f"{target} is outside the project at {root}")
    shown = path.relative_to(base).as_posix()
    if not path.parent.is_dir():
        raise WriteError(f"the directory does not exist for {shown}")
    content = render(path, version)
    try:
        if path.is_file() and path.read_text(encoding="utf-8") == content:
            return WriteResult(WriteStatus.UNCHANGED, shown, content)
        if dry_run:
            return WriteResult(WriteStatus.WOULD_WRITE, shown, content)
        _replace(path, content)
    except OSError as e:
        raise WriteError(f"cannot write {shown}: {e}") from e
    return WriteResult(WriteStatus.WROTE, shown, content)


def _replace(path: Path, content: str) -> None:
    """Write beside the target, then rename over it, so no reader sees half a file."""
    handle, name = tempfile.mkstemp(dir=path.parent, prefix=f".{path.name}.")
    try:
        with os.fdopen(handle, "w", encoding="utf-8") as stream:
            stream.write(content)
        os.replace(name, path)
    except BaseException:
        with contextlib.suppress(OSError):
            Path(name).unlink()
        raise
